        raise ValueError("top-level value must be a JSON object")
    keys = tuple(value)
    if keys != _PAIR_GATE_SCORE_SUMMARY_KEYS:
        raise ValueError(
            "keys must be exactly in the order "
            "coverage_product, score_margin, matched, pair_quality, quality"
        )

